def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return max(0.0, min(budget, 45.0))
        return max(0.0, min(budget, 18.0))

    prev_bids = []
    pressure_bids = []
    rich_live = 0
    desperate_live = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_live += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_live += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > 0 and opp.get('hp', 10) > 0:
                pressure_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    live_pressure = max(pressure_bids) if pressure_bids else highest_prev

    units = supply / float(WATER_REQ)
    crowded = units < 1.6
    medium_tight = units < 1.9

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1
    if day >= 8:
        urgency += 1

    if urgency >= 5:
        base = 0.92 * DAILY_SALARY
        if crowded:
            base = max(base, live_pressure + 4.0)
        return max(0.0, min(budget, base))

    if urgency >= 3:
        if crowded:
            bid = max(0.72 * DAILY_SALARY, min(0.95 * DAILY_SALARY, live_pressure + 2.5))
        elif medium_tight:
            bid = max(0.58 * DAILY_SALARY, min(0.82 * DAILY_SALARY, live_pressure * 0.72 + 2.0))
        else:
            bid = max(0.42 * DAILY_SALARY, min(0.68 * DAILY_SALARY, live_pressure * 0.55 + 1.5))
        return max(0.0, min(budget, bid))

    if crowded:
        if live_pressure >= 120:
            bid = 16.0
        elif live_pressure >= 80:
            bid = 22.0
        else:
            bid = max(24.0, min(40.0, live_pressure * 0.45 + 3.0))
    elif medium_tight:
        if live_pressure >= 120:
            bid = 14.0
        elif live_pressure >= 80:
            bid = 18.0
        else:
            bid = max(16.0, min(30.0, live_pressure * 0.35 + 2.0))
    else:
        bid = 12.0

    if desperate_live >= 2:
        bid += 4.0
    elif desperate_live == 1:
        bid += 2.0

    if rich_live >= 3 and live_pressure > 90:
        bid = min(bid, 20.0)

    if budget < 25:
        bid = min(bid, max(8.0, budget * 0.75))

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for o in opponents_status.values():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # React to yesterday bids (immediate trace only)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Pressure estimate: if opponents were bidding near/above our daily salary, they likely continue.
    aggressive_market = highest_prev_bid >= DAILY_SALARY * 0.85

    # Base bid depends on current supply: higher supply reduces need to outbid.
    # supply in [15,25] => target fraction of daily salary.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    if aggressive_market:
        # If they were aggressive, we bid enough to avoid being starved.
        # If my HP is low, bid closer to daily salary; otherwise moderate.
        if hp <= 2.5 or no_water_days >= 2:
            target = DAILY_SALARY * (0.85 - 0.15 * supply_norm)
        else:
            target = DAILY_SALARY * (0.65 - 0.10 * supply_norm)
    else:
        # If they weren't aggressive, bid just above a reasonable threshold.
        target = DAILY_SALARY * (0.55 - 0.10 * supply_norm)

    # Ensure we don't exceed budget; also keep some reserve for later days.
    # Reserve more when HP is comfortable.
    reserve_factor = 0.25 if hp <= 2.5 else 0.35
    max_affordable = max(0.0, budget * (1.0 - reserve_factor))

    bid = min(max_affordable, target)

    # If budget is tiny, still bid what we can.
    if bid <= 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    # Slightly nudge up on early days to secure water before opponents can snowball.
    if day <= 3:
        bid = min(budget, bid * 1.12)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(prev_bids)
    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev * 1.1 + 5.0)

    if day_context['supply'] < WATER_REQ * 1.5:
        return min(my_status['budget'], max_prev + 2.0)

    return min(my_status['budget'], max(DAILY_SALARY * 0.4, max_prev * 0.8))
